import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {chromium} from 'playwright-core';
const out=process.env.TRADING_EVIDENCE_DIR;assert.ok(out&&process.env.TRADING_CDP_URL);
const browser=await chromium.connectOverCDP(process.env.TRADING_CDP_URL),page=browser.contexts()[0].pages().find(p=>p.url().includes('/trading-proof'));page.setDefaultTimeout(12000);
const evidence={views:[],errors:[]};page.on('pageerror',e=>evidence.errors.push(e.message));
const panel=()=>page.locator('[data-panel-id]:visible').filter({has:page.locator('[data-workspace-section="chart"]')}).first();
const top=()=>page.evaluate(()=>{document.activeElement?.blur();document.querySelectorAll('*').forEach(e=>{if(e.scrollTop)e.scrollTop=0;});});
async function bounds(){return panel().evaluate(e=>{const box=s=>e.querySelector(s).getBoundingClientRect().toJSON(),rows=[...e.querySelectorAll('[data-workspace-section="details"] tbody tr')],scroll=e.querySelector('[class*="TerminalDiscovery_scroll"]');return{chart:box('[data-workspace-section="chart"]'),trade:box('[data-workspace-section="trade"]'),details:box('[data-workspace-section="details"]'),visibleCoins:rows.filter(row=>row.getBoundingClientRect().bottom<=innerHeight).length,discoveryInnerScroll:scroll?scroll.scrollHeight>scroll.clientHeight+1:null};});}
async function plotFits(){const frame=panel().getByRole('group',{name:'Inspect price history',exact:true});await frame.focus();await page.keyboard.press('End');const r=await frame.evaluate(e=>{const c=e.querySelector('[class*="_canvas_"]').getBoundingClientRect(),b=e.getBoundingClientRect(),t=e.querySelector('[class*="_timeAxis_"]').getBoundingClientRect(),stage=e.closest('[class*="_chartStage_"]').getBoundingClientRect();return{right:b.right-c.right,h:c.height,time:t.bottom,bottom:stage.bottom};});assert.ok(Math.abs(r.right-4)<1&&r.h>40&&r.time<=r.bottom+1);await page.keyboard.press('Escape');}
try{
 await page.bringToFront();await page.setViewportSize({width:1414,height:1000});await page.emulateMedia({reducedMotion:'reduce'});const cdp=await page.context().newCDPSession(page);await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});await page.reload();await page.waitForFunction(()=>typeof document.getElementById('trading-open')?.onclick==='function');if(!await page.locator('[data-workspace-host]').count())await page.locator('#trading-open').click();await page.waitForFunction(()=>!!window.tradingFixture);await page.evaluate(()=>window.tradingFixture.store.setLayout({order:['chart','activity','trade','details'],hidden:[],split:64}));
 await panel().locator('[data-panel-amount]').fill('123.45');await page.waitForFunction(()=>[...document.querySelectorAll('[data-panel-id="A"] button')].some(b=>b.textContent==='Buy KSTL'&&!b.disabled));await top();const initial=await bounds();assert.ok(initial.chart.height<=400,JSON.stringify(initial));assert.ok(initial.visibleCoins>=5);assert.equal(initial.discoveryInnerScroll,false);evidence.default=initial;
 for(const theme of ['light','dark'])for(const width of [320,407,768,1054,1414]){
  await page.setViewportSize({width,height:1000});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:width<1024,maxTouchPoints:1});await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await page.waitForTimeout(150);await top();assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);
  const trade=panel().getByRole('region',{name:'Trade',exact:true});if(await trade.count())assert.ok(await trade.evaluate(e=>{const card=e.closest('[data-workspace-section]');return card.scrollWidth<=card.clientWidth+1;}));await plotFits();await top();const g=await bounds();if(width>=1054){assert.equal(g.details.x,g.chart.x);assert.equal(g.details.right,g.trade.right);assert.ok(Math.abs(g.details.y-g.chart.bottom-6)<1);}
  await page.screenshot({path:out+`/coin-${theme}-${width}.png`});evidence.views.push({theme,width,...g});
 }
 await page.setViewportSize({width:1414,height:1000});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:false});const h=panel().getByRole('separator',{name:/height/});const initialHeight=Number(await h.getAttribute('aria-valuenow'));const hb=await h.boundingBox();await page.mouse.move(hb.x+hb.width/2,hb.y+hb.height/2);await page.mouse.down();await page.mouse.move(hb.x+hb.width/2,hb.y+hb.height/2+80,{steps:6});await page.mouse.up();await page.waitForTimeout(100);assert.equal(Number(await h.getAttribute('aria-valuenow')),initialHeight+80);await h.focus();await page.keyboard.press('Home');await plotFits();assert.equal(await panel().locator('[data-panel-amount]').inputValue(),'123.45');
 await page.getByRole('button',{name:'Edit layout',exact:true}).click();await panel().getByRole('button',{name:'Move Trade earlier',exact:true}).click();assert.equal(await panel().locator('[data-panel-amount]').inputValue(),'123.45');await page.getByRole('button',{name:'Cancel',exact:true}).click();
 for(const status of ['quote-loading','quote-error']){await page.evaluate(s=>window.tradingFixture.state('A',s),status);if(status==='quote-error')await panel().getByRole('alert').filter({hasText:'The quote could not load.'}).waitFor();else await panel().getByRole('status',{name:'Getting a current quote',exact:true}).waitFor();await top();const g=await bounds();assert.ok(Math.abs(g.details.y-g.trade.bottom-6)<1);await page.screenshot({path:out+`/${status}.png`});}await page.evaluate(()=>window.tradingFixture.state('A','ready'));await page.waitForFunction(()=>[...document.querySelectorAll('[data-panel-id="A"] button')].some(b=>b.textContent==='Buy KSTL'&&!b.disabled));
 await top();for(const theme of ['light','dark']){await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await page.screenshot({path:out+`/final-${theme}.png`});}
 const d=panel().getByRole('region',{name:'Discover markets',exact:true});await d.getByRole('button',{name:'Presales',exact:true}).click();await d.getByRole('button',{name:'Open NOVA presale',exact:true}).click();await panel().getByRole('textbox',{name:'Commit amount'}).fill('100');await page.waitForFunction(()=>[...document.querySelectorAll('[data-presale-submit]')].some(b=>b.textContent==='Commit'&&!b.disabled));
 for(const width of [320,1414])for(const theme of ['light','dark']){await page.setViewportSize({width,height:1000});await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:width<1024,maxTouchPoints:1});await page.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await page.waitForTimeout(100);await top();assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await page.screenshot({path:out+`/presale-${theme}-${width}.png`});}
 await page.emulateMedia({contrast:'more'});await page.screenshot({path:out+'/increased-contrast.png'});await page.emulateMedia({contrast:'no-preference'});await cdp.send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-transparency',value:'reduce'}]});await page.screenshot({path:out+'/reduced-transparency.png'});assert.deepEqual(evidence.errors,[]);writeFileSync(out+'/compact-verification.json',JSON.stringify(evidence,null,2));console.log('PASS compact default, five visible coins, five widths/two themes, chart clearance, resizing, preserved drafts, quote states and presale regression');
}finally{await browser.close();}
